/*!
 * \file chunk_gated_delta_rule_recurrence_proto.cpp
 * \brief
 */

#include <graph/utils/type_utils.h>
#include <register/op_impl_registry.h>
#include "log/ops_log.h"
#include "error/ops_error.h"

using namespace ge;

namespace ops {
// INPUT
constexpr uint32_t INITIAL_STATE_INPUT_INDEX = 0;
constexpr uint32_t VALUE_INPUT_INDEX = 2;

// OUTPUT
constexpr uint32_t INITIAL_STATE_OUTPUT_INDEX = 0;
constexpr uint32_t ATTN_INTER_OUT_OUTPUT_INDEX = 1;
constexpr uint32_t V_NEW_OUT_OUTPUT_INDEX = 2;


static ge::graphStatus SetShapeDim(gert::InferShapeContext* context)
{
    auto initialStateInputShape = context->GetRequiredInputShape(INITIAL_STATE_INPUT_INDEX);
    auto valueShape = context->GetRequiredInputShape(VALUE_INPUT_INDEX);

    OPS_LOG_E_IF_NULL(context, initialStateInputShape, return ge::GRAPH_FAILED);
    OPS_LOG_E_IF_NULL(context, valueShape, return ge::GRAPH_FAILED);

    auto initialStateOutputShape = context->GetOutputShape(INITIAL_STATE_OUTPUT_INDEX);
    auto attnInterOutShape = context->GetOutputShape(ATTN_INTER_OUT_OUTPUT_INDEX);
    auto vNewOutShape = context->GetOutputShape(V_NEW_OUT_OUTPUT_INDEX);

    OPS_LOG_E_IF_NULL(context, initialStateOutputShape, return ge::GRAPH_FAILED);
    OPS_LOG_E_IF_NULL(context, attnInterOutShape, return ge::GRAPH_FAILED);
    OPS_LOG_E_IF_NULL(context, vNewOutShape, return ge::GRAPH_FAILED);

    *initialStateOutputShape = *initialStateInputShape;
    *attnInterOutShape = *valueShape;
    *vNewOutShape = *valueShape;

    return GRAPH_SUCCESS;
}

ge::graphStatus InferShape_ChunkGatedDeltaRuleRecurrence(gert::InferShapeContext* context)
{
    OPS_LOG_I(context->GetNodeName(), "Enter InferShape impl.");

    OPS_ERR_IF(SetShapeDim(context) != GRAPH_SUCCESS,
        OPS_LOG_E(context->GetNodeName(), "InferShape failed!"),
        return ge::GRAPH_FAILED
    );

    OPS_LOG_I(context->GetNodeName(), "InferShape end.");
    return GRAPH_SUCCESS;
}

ge::graphStatus InferDataType_ChunkGatedDeltaRuleRecurrence(gert::InferDataTypeContext* context)
{
    OPS_LOG_I(context->GetNodeName(), "Enter InferDataType impl.");

    auto initialStateInputDataType = context->GetRequiredInputDataType(INITIAL_STATE_INPUT_INDEX);
    auto valueDataType = context->GetRequiredInputDataType(VALUE_INPUT_INDEX);

    context->SetOutputDataType(INITIAL_STATE_OUTPUT_INDEX, initialStateInputDataType);
    context->SetOutputDataType(ATTN_INTER_OUT_OUTPUT_INDEX, valueDataType);
    context->SetOutputDataType(V_NEW_OUT_OUTPUT_INDEX, valueDataType);

    OPS_LOG_I(context->GetNodeName(), "InferDataType end.");
    return GRAPH_SUCCESS;
}

IMPL_OP_INFERSHAPE(AiInfraChunkGatedDeltaRuleRecurrence)
    .InferShape(InferShape_ChunkGatedDeltaRuleRecurrence)
    .InferDataType(InferDataType_ChunkGatedDeltaRuleRecurrence);

}

