9	*/
10	
11	/*!
12	 * \file matmul_common_infershape.cpp
13	 * \brief
14	 */
15	#include "matmul_common_infershape.h"
16	#include "op_common/log/log.h"
17	using namespace gert;
18	namespace {
19	constexpr size_t BATCH_MATMUL_MIN_SHAPE_SIZE = 2;
20	constexpr size_t BATCH_MATMUL_MAX_SHAPE_SIZE = 8;
21	constexpr size_t BATCH_MATMUL_BIAS_IDX = 2; // input_bias index is different with op_type
22	constexpr size_t BATCH_MATMUL_FIXPIPE_BIAS_IDX = 3;
23	constexpr size_t SWIGLU_CONCAT_WEIGHT_DIM_NUM = 3;
24	constexpr int64_t UNKNOWN_DIM = -1;
25	constexpr int64_t UNKNOWN_DIM_NUM = -2;
26	constexpr int64_t DIM_INDEX_FIRST = 0;
27	constexpr int64_t DIM_INDEX_SECOND = 1;
28	constexpr int64_t DIM_INDEX_THIRD = 2;
29	constexpr int64_t SWIGLU_CONCAT_DIM_VALUE = 2;
30	const int64_t B4_NUMS_IN_B32 = 8;
31	constexpr char FUSED_OP_TYPE_SWIGLU[] = "swiglu";
32	
33	struct InferShapeBatchTensor {
34	    const Shape input_shape_a;
35	    const Shape input_shape_b;
36	    bool input_trans_a;
37	    bool input_trans_b;
38	};
39	
40	class InferShapeBatchMatMul {
41	public:
42	    InferShapeBatchMatMul(
43	        gert::InferShapeContext* context, const InferShapeBatchTensor& inferShapeTensor,
44	        size_t batch_matmul_bias_index = BATCH_MATMUL_BIAS_IDX)
45	        : op_name(context->GetNodeName()),
46	          shape_a(inferShapeTensor.input_shape_a),
47	          shape_b(inferShapeTensor.input_shape_b),
48	          trans_a(inferShapeTensor.input_trans_a),
49	          trans_b(inferShapeTensor.input_trans_b),
50	          shape_out(*(context->GetOutputShape(0))),
51	          shape_bias(context->GetOptionalInputShape(batch_matmul_bias_index))
52	    {
53	        num_dima = shape_a.GetDimNum();
54	        num_dimb = shape_b.GetDimNum();
55	        num_dim = std::max(num_dima, num_dimb);
56	        num_dim_bias = 0;
57	        if (shape_bias != nullptr) {
58	            num_dim_bias = shape_bias->GetDimNum();
59	            num_dim = std::max(num_dim, num_dim_bias);
60	        }
61	        shape_out.SetDimNum(num_dim);
62	    };
63	
64	    InferShapeBatchMatMul(gert::InferShapeContext* context, const Shape& input_shape_a, const Shape& input_shape_b)
65	        : op_name(context->GetNodeName()),
66	          shape_a(input_shape_a),
67	          shape_b(input_shape_b),
68	          shape_out(*(context->GetOutputShape(0)))
69	    {
70	        shape_bias = context->GetOptionalInputShape(BATCH_MATMUL_FIXPIPE_BIAS_IDX);
71	        num_dima = shape_a.GetDimNum();
72	        num_dimb = shape_b.GetDimNum();
73	        num_dim = std::max(num_dima, num_dimb);
74	        auto attrs = context->GetAttrs();
75	        trans_a = *(attrs->GetAttrPointer<bool>(0));
76	        trans_b = *(attrs->GetAttrPointer<bool>(1));
77	        num_dim_bias = 0;
78	        if (shape_bias != nullptr) {
79	            num_dim_bias = shape_bias->GetDimNum();
80	            num_dim = std::max(num_dim, num_dim_bias);
81	        }
82	        shape_out.SetDimNum(num_dim);
83	    };
84	
85	    ~InferShapeBatchMatMul(){};
86	    bool InferShape();
87	
88	protected:
89	    bool InferBatch() const;
90	    bool InferBias();
91	
92	    size_t num_dim = 0;
93	    size_t num_dima = 0;
94	    size_t num_dimb = 0;
95	    size_t num_dim_bias = 0;
96	
97	    const char* op_name;
98	    const Shape& shape_a;
99	    const Shape& shape_b;
100	    bool trans_a = false;
101	    bool trans_b = false;
102	    Shape& shape_out;
103	    const Shape* shape_bias;
104	};
105	
106	static void CopyOutShapeFromInputShape(const Shape& shape_in, Shape& shape_out, int64_t valid_offset)
107	{
108	    for (auto i = 0; i < valid_offset; ++i) {
109	        shape_out.SetDim(i, shape_in.GetDim(i));
110	    }
111	}
112	
113	bool InferShapeBatchMatMul::InferBatch() const
114	{
115	    auto valid_offset = num_dim - std::min(num_dima, num_dimb);
116	    const Shape& shape_long = num_dima < num_dimb ? shape_b : shape_a;
117	    const Shape& shape_short = num_dima < num_dimb ? shape_a : shape_b;
118	    int64_t shape_value_long;
119	    int64_t shape_value_short;
120	
121	    CopyOutShapeFromInputShape(shape_long, shape_out, valid_offset);
122	    // use index - 2 to get index of m
123	    for (auto i = valid_offset; i < num_dim - 2; ++i) {
124	        shape_value_short = shape_short.GetDim(i - valid_offset);
125	        shape_value_long = shape_long.GetDim(i);
126	        if (shape_value_short > 1 && shape_value_long > 1 && shape_value_short != shape_value_long) {
127	            return false;
128	        }
129	        // 适配一根轴为1，一根轴为-1的情况
130	        if (shape_value_short == 1) {
131	            shape_out.SetDim(i, shape_value_long);
132	        } else if (shape_value_long == 1) {
133	            shape_out.SetDim(i, shape_value_short);
134	        } else {
135	            shape_out.SetDim(i, std::max(shape_value_short, shape_value_long));
136	        }
137	    }
138	    return true;
139	}
140	
141	static bool BroadcastBatchDim(const char* op_name, const int64_t dim_a, const int64_t dim_b, int64_t& dim)
142	{
143	    if (dim_a > 1 && dim_b > 1) {
144	        OP_CHECK_IF(
145	            dim_a != dim_b,
146	            CUBE_INNER_ERR_REPORT(op_name, "[InferShape] dimensions a(%ld) and b(%ld) must be equal", dim_a, dim_b),
147	            return false);
148	
149	        dim = dim_a;
150	        return true;
151	    }
152	    // 适配一根轴为1，一根轴为-1的情况
153	    if (dim_a == 1) {
154	        dim = dim_b;
155	        return true;
156	    }
157	    if (dim_b == 1) {
158	        dim = dim_a;
159	        return true;
160	    }
161	    dim = std::max(dim_a, dim_b);
162	    return true;
163	}
164	
165	static bool InferNWithBias(const char* op_name, const int64_t bias_n, const int64_t out_n, int64_t& n)
166	{
167	    if (bias_n == UNKNOWN_DIM || bias_n == UNKNOWN_DIM_NUM) {
168	        // 当bias中的n为动态shape，不改变最终输出的n
169	        return true;
170	    }
171	    if (bias_n > 0 && out_n > 0) {
172	        OP_CHECK_IF(
173	            bias_n != out_n,
174	            CUBE_INNER_ERR_REPORT(
175	                op_name, "[InferShape] dimensions bias_n(%ld) and out_n(%ld) must be equal", bias_n, out_n),
176	            return false);
177	        n = bias_n;
178	        return true;
179	    }
180	    if (out_n == UNKNOWN_DIM && bias_n > 0) {
181	        n = bias_n;
182	        return true;
183	    }
184	
185	    return false;
186	}
