188	bool InferShapeBatchMatMul::InferBias()
189	{
190	    int64_t shape_value_out = shape_out.GetDim(num_dim - 1);
191	    // 1) shape_bias = {}
192	    OP_CHECK_IF(
193	        num_dim_bias == 0, CUBE_INNER_ERR_REPORT(op_name, "[InferShape] bias dims number is zero"), return true);
194	    OP_CHECK_IF(shape_bias->GetShapeSize() == 0, OP_LOGI(op_name, "[InferShape] bias shape size is zero"), return true);
195	
196	    // 2) infer n with bias
197	    OP_CHECK_IF(
198	        !InferNWithBias(op_name, shape_bias->GetDim(num_dim_bias - 1), shape_out.GetDim(num_dim - 1), shape_value_out),
199	        CUBE_INNER_ERR_REPORT(op_name, "[InferShape] failed. infer N dim with bias"), return false);
200	
201	    shape_out.SetDim(num_dim - 1, shape_value_out);
202	
203	    // 3) infer batch with bias
204	    auto valid_offset = num_dim - std::min(num_dim_bias, std::max(num_dima, num_dimb));
205	    if (num_dim_bias < num_dim) {
206	        // stop before num_dim - 2 so as to avoid traversing axis m, n
207	        for (auto i = valid_offset; i < num_dim - 2; ++i) {
208	            OP_CHECK_IF(
209	                !BroadcastBatchDim(op_name, shape_bias->GetDim(i - valid_offset), shape_out.GetDim(i), shape_value_out),
210	                CUBE_INNER_ERR_REPORT(op_name, "[InferShape] Failed to broadcast batch dim"), return false);
211	
212	            shape_out.SetDim(i, shape_value_out);
213	        }
214	        return true;
215	    }
216	    CopyOutShapeFromInputShape(*shape_bias, shape_out, valid_offset);
217	    // stop before num_dim - 2 so as to avoid traversing axis m, n
218	    for (auto i = valid_offset; i < num_dim - 2; ++i) {
219	        OP_CHECK_IF(
220	            !BroadcastBatchDim(op_name, shape_bias->GetDim(i), shape_out.GetDim(i - valid_offset), shape_value_out),
221	            CUBE_INNER_ERR_REPORT(op_name, "[InferShape] Failed to broadcast batch dim"), return false);
222	
223	        shape_out.SetDim(i, shape_value_out);
224	    }
225	    return true;
226	}
