228	bool InferShapeBatchMatMul::InferShape()
229	{
230	    if (shape_a.GetDimNum() < BATCH_MATMUL_MIN_SHAPE_SIZE || shape_b.GetDimNum() < BATCH_MATMUL_MIN_SHAPE_SIZE) {
231	        CUBE_INNER_ERR_REPORT(
232	            op_name,
233	            "[InferShape] Invalid input: The rank (number of dimensions) of tensors x1 and x2 must be at least 2.");
234	        return false;
235	    }
236	    for (size_t i = 0; i < shape_a.GetDimNum(); ++i) {
237	        OP_CHECK_IF(
238	            shape_a.GetDim(i) < UNKNOWN_DIM_NUM,
239	            CUBE_INNER_ERR_REPORT(
240	                op_name,
241	                "[InferShape] Invalid x1 [%zu] dimension: value %ld is less than the minimum allowed value (-2)", i,
242	                static_cast<int64_t>(shape_a.GetDim(i))),
243	            return false);
244	    }
245	    for (size_t i = 0; i < shape_b.GetDimNum(); ++i) {
246	        OP_CHECK_IF(
247	            shape_b.GetDim(i) < UNKNOWN_DIM_NUM,
248	            CUBE_INNER_ERR_REPORT(
249	                op_name,
250	                "[InferShape] Invalid x2 [%zu] dimension: value %ld is less than the minimum allowed value (-2)", i,
251	                static_cast<int64_t>(shape_b.GetDim(i))),
252	            return false);
253	    }
254	    // using index - 2 to get m_dim
255	    size_t idx_m = num_dima - 2;
256	    size_t idx_k_a = num_dima - 1;
257	    // using index - 2 to get k_dim
258	    size_t idx_k_b = num_dimb - 2;
259	    size_t idx_n = num_dimb - 1;
260	    if (trans_a) {
261	        idx_m = num_dima - 1;
262	        // using index - 2 to get k_dim
263	        idx_k_a = num_dima - 2;
264	    }
265	    if (trans_b) {
266	        idx_k_b = num_dimb - 1;
267	        // using index - 2 to get n_dim
268	        idx_n = num_dimb - 2;
269	    }
270	
271	    // Check k dim in static shape
272	    if ((shape_a.GetDim(idx_k_a) != UNKNOWN_DIM && shape_b.GetDim(idx_k_b) != UNKNOWN_DIM) &&
273	        (shape_a.GetDim(idx_k_a) != shape_b.GetDim(idx_k_b))) {
274	        CUBE_INNER_ERR_REPORT(
275	            op_name, "[InferShape] The k-axis of a(%ld) and b(%ld) tensors must be the same", shape_a.GetDim(idx_k_a),
276	            shape_b.GetDim(idx_k_b));
277	        return false;
278	    }
279	    OP_CHECK_IF(!InferBatch(), CUBE_INNER_ERR_REPORT(op_name, "[InferShape] failed. infer Batch."), return false);
280	
281	    // using index - 2 to get m_dim in shape_out
282	    shape_out.SetDim((num_dim - 2), shape_a.GetDim(idx_m));
283	    shape_out.SetDim((num_dim - 1), shape_b.GetDim(idx_n));
284	    if (shape_bias != nullptr) {
285	        OP_CHECK_IF(!InferBias(), CUBE_INNER_ERR_REPORT(op_name, "[InferShape] Infer bias failed."), return false);
286	    }
287	    return true;
288	}
