290	static void InferComplementedOutput(bool shape_x1_reshape_flag, bool shape_x2_reshape_flag, Shape& shape_out)
291	{
292	    size_t dim_num = shape_out.GetDimNum();
293	    if (dim_num >= BATCH_MATMUL_MIN_SHAPE_SIZE) {
294	        if (shape_x1_reshape_flag && !shape_x2_reshape_flag) {
295	            shape_out.SetDim(dim_num - BATCH_MATMUL_MIN_SHAPE_SIZE, shape_out.GetDim(dim_num - 1));
296	            shape_out.SetDimNum(dim_num - 1);
297	        }
298	
299	        if (!shape_x1_reshape_flag && shape_x2_reshape_flag) {
300	            shape_out.SetDimNum(dim_num - 1);
301	        }
302	    }
303	}
