313	static bool CalculateTransX2Float(
314	    const gert::InferShapeContext* context, const Shape& shape_x2, bool trans_x1, bool trans_x2)
315	{
316	    auto shape_x1 = context->GetInputShape(0);
317	    auto x1_dim_num = shape_x1->GetDimNum();
318	    size_t x2_dim_num = shape_x2.GetDimNum();
319	    size_t k_x1_dim = trans_x1 ? (x1_dim_num - 2UL) : (x1_dim_num - 1UL);
320	    size_t k_x2_dim = trans_x2 ? (x2_dim_num - 1UL) : (x2_dim_num - 2UL);
321	    if (!trans_x1 && !trans_x2) {
322	        return shape_x1->GetDim(k_x1_dim) == shape_x2.GetDim(k_x2_dim) * B4_NUMS_IN_B32;
323	    }
324	    return false;
325	}
