327	static ge::graphStatus UpdateX2NewShape(
328	    const gert::InferShapeContext* context, Shape& new_shape, bool& reshape_flag, bool trans_x1, bool trans_x2,
329	    const bool is_packed, const char* fused_op_type)
330	{
331	    auto op_name = context->GetNodeName();
332	    if (new_shape.GetDimNum() == 1 && new_shape.GetDim(0) > UNKNOWN_DIM_NUM) {
333	        reshape_flag = true;
334	        int64_t ori_dim = new_shape.GetDim(0);
335	        new_shape.SetDimNum(BATCH_MATMUL_MIN_SHAPE_SIZE);
336	        new_shape.SetDim(0, ori_dim);
337	        new_shape.SetDim(1, 1);
338	    }
339	
340	    if (is_packed) {
341	        auto* desc = context->GetInputDesc(1);
342	        OP_CHECK_IF(
343	            desc == nullptr, CUBE_INNER_ERR_REPORT(op_name, "[InferShape] x2 is null"), return ge::GRAPH_FAILED);
344	        size_t dim_num = new_shape.GetDimNum();
345	        size_t x2_dim_num = new_shape.GetDimNum();
346	        size_t k_x2_dim = trans_x2 ? (x2_dim_num - 1UL) : (x2_dim_num - 2UL);
347	        size_t n_x2_dim = trans_x2 ? (x2_dim_num - 2UL) : (x2_dim_num - 1UL);
348	        int64_t k_dim = new_shape.GetDim(k_x2_dim);
349	        int64_t n_dim = new_shape.GetDim(n_x2_dim);
350	        if (desc->GetDataType() == ge::DT_FLOAT && k_dim > 0 && n_dim > 0) {
351	            OP_CHECK_IF(
352	                dim_num < 1UL, CUBE_INNER_ERR_REPORT(op_name, "[InferShape] The shape of x2 should not smaller than 1"),
353	                return ge::GRAPH_FAILED);
354	            bool trans_x2_float = CalculateTransX2Float(context, new_shape, trans_x1, trans_x2);
355	            if (trans_x2 || trans_x2_float) {
356	                new_shape.SetDim(k_x2_dim, new_shape.GetDim(k_x2_dim) * B4_NUMS_IN_B32);
357	            } else {
358	                new_shape.SetDim(n_x2_dim, new_shape.GetDim(n_x2_dim) * B4_NUMS_IN_B32);
359	            }
360	        }
361	    }
362	
363	    if (strcmp(fused_op_type, FUSED_OP_TYPE_SWIGLU) == 0) {
364	        if (new_shape.GetDimNum() != SWIGLU_CONCAT_WEIGHT_DIM_NUM) {
365	            CUBE_INNER_ERR_REPORT(op_name,
366	                "[InferShape] For swiglu fused operation, x2 shape must be 3-dimensional, \
367	                but got %zu dimensions (shape: %s)", new_shape.GetDimNum(), Ops::Base::ToString(new_shape).c_str());
368	            return ge::GRAPH_FAILED;
369	        }
370	
371	        int64_t highest_dim = new_shape.GetDim(0);
372	        // the highest dimension (dimension 0) equals 2 (indicating concatenation of two weights)
373	        if (highest_dim != SWIGLU_CONCAT_DIM_VALUE) {
374	            CUBE_INNER_ERR_REPORT(op_name,
375	                "[InferShape] For swiglu fused operation, the highest dimension must be 2, but got %ld", highest_dim);
376	            return ge::GRAPH_FAILED;
377	        }
378	
379	        // remove the highest dimension (value 2) to perform normal matmul inferShape
380	        new_shape.SetDimNum(BATCH_MATMUL_MIN_SHAPE_SIZE);
381	        new_shape.SetDim(DIM_INDEX_FIRST, new_shape.GetDim(DIM_INDEX_SECOND));
382	        new_shape.SetDim(DIM_INDEX_SECOND, new_shape.GetDim(DIM_INDEX_THIRD));
383	    }
384	
385	    return ge::GRAPH_SUCCESS;
386	}
