388	ge::graphStatus InferShapeForBatchMatMul(
389	    gert::InferShapeContext* context, const int32_t attr_adj_idx, const size_t input_bias_index,
390	    const bool is_x2_packed, const char* fused_op_type)
391	{
392	    auto shape_x1 = context->GetInputShape(0);
393	    auto shape_x2 = context->GetInputShape(1);
394	    auto shape_out = context->GetOutputShape(0);
395	    auto attrs = context->GetAttrs();
396	    auto op_name = context->GetNodeName();
397	    OP_CHECK_IF(shape_x1 == nullptr || shape_x2 == nullptr || shape_out == nullptr,
398	        CUBE_INNER_ERR_REPORT(op_name, "[InferShape] shape is null"), return ge::GRAPH_FAILED);
399	    if (CheckIsUnknownDimNum(*shape_x1) || CheckIsUnknownDimNum(*shape_x2)) {
400	        shape_out->SetDimNum(1);
401	        shape_out->SetDim(0, UNKNOWN_DIM_NUM);
402	        return ge::GRAPH_SUCCESS;
403	    }
404	    OP_CHECK_IF(attrs == nullptr,
405	        CUBE_INNER_ERR_REPORT(op_name, "[InferShape] attrs is null"), return ge::GRAPH_FAILED);
406	    const bool* adj_x1 = attrs->GetAttrPointer<bool>(attr_adj_idx);
407	    const bool* adj_x2 = attrs->GetAttrPointer<bool>(attr_adj_idx + 1);
408	
409	    OP_CHECK_IF(adj_x1 == nullptr || adj_x2 == nullptr,
410	        CUBE_INNER_ERR_REPORT(op_name, "[InferShape] attribute is null"), return ge::GRAPH_FAILED);
411	
412	    OP_LOGD(
413	        context->GetNodeName(), "x1_shape: %s, x2_shape: %s, adj_x1: %d, adj_x2: %d",
414	        Ops::Base::ToString(*shape_x1).c_str(), Ops::Base::ToString(*shape_x2).c_str(), *adj_x1, *adj_x2);
415	
416	    auto dim_num = std::max(shape_x1->GetDimNum(), shape_x2->GetDimNum());
417	    if (dim_num < 1 || dim_num > BATCH_MATMUL_MAX_SHAPE_SIZE) {
418	        CUBE_INNER_ERR_REPORT(op_name, "[InferShape] The shape can only be in the range of 1 to 8.");
419	        return ge::GRAPH_FAILED;
420	    }
421	
422	    // 补充bmmv3单轴逻辑，输入的单轴代表的都是k轴
423	    Shape shape_x2_new(*shape_x2);
424	    bool shape_x2_reshape_flag = false;
425	    if (UpdateX2NewShape(context, shape_x2_new, shape_x2_reshape_flag, *adj_x1, *adj_x2, is_x2_packed, fused_op_type) !=
426	        ge::GRAPH_SUCCESS) {
427	        return ge::GRAPH_FAILED;
428	    }
429	
430	    Shape shape_x1_new(*shape_x1);
431	    bool shape_x1_reshape_flag = false;
432	    if (shape_x1_new.GetDimNum() == 1 && shape_x1_new.GetDim(0) > UNKNOWN_DIM_NUM) {
433	        shape_x1_reshape_flag = true;
434	        int64_t ori_dim = shape_x1_new.GetDim(0);
435	        shape_x1_new.SetDimNum(BATCH_MATMUL_MIN_SHAPE_SIZE);
436	        shape_x1_new.SetDim(0, 1);
437	        shape_x1_new.SetDim(1, ori_dim);
438	    }
439	
440	    InferShapeBatchTensor InferShapeBatchTensor = {
441	        shape_x1_new, shape_x2_new, *adj_x1 && !shape_x1_reshape_flag, *adj_x2 && !shape_x2_reshape_flag};
442	    InferShapeBatchMatMul batchMatMulInfer(context, InferShapeBatchTensor, input_bias_index);
443	    OP_CHECK_IF(!batchMatMulInfer.InferShape(),
444	        CUBE_INNER_ERR_REPORT(op_name, "[InferShape] Failed to infer output shape"), return ge::GRAPH_FAILED);
445	
446	    InferComplementedOutput(shape_x1_reshape_flag, shape_x2_reshape_flag, *shape_out);
447	    OP_LOGD(context->GetNodeName(), "output shape: %s", Ops::Base::ToString(*(context->GetOutputShape(0))).c_str());
448	    // no need to SetDataType in runtime
449	    return ge::GRAPH_SUCCESS;
450	}
