452	// range相关逻辑
453	constexpr int64_t INFINITE_RANGE = -1;
454	constexpr int64_t NORMALIZE_INFINITE_RANGE = std::numeric_limits<int64_t>::max();
455	static const std::pair<int64_t, int64_t> NORMALIZE_FULL_RANGE = {0, NORMALIZE_INFINITE_RANGE};
456	static bool InitializeRange(
457	    size_t num, const std::vector<std::pair<int64_t, int64_t>>& range,
458	    std::vector<std::pair<int64_t, int64_t>>& new_range)
459	{
460	    // 扩充batch轴为1
461	    for (size_t i = 0; i < num - range.size(); ++i) {
462	        std::pair<int64_t, int64_t> new_dim = {1, 1};
463	        new_range.emplace_back(new_dim);
464	    }
465	    for (size_t i = 0; i < range.size(); ++i) {
466	        if (range.at(i).first < 0) {
467	            OP_LOGE(
468	                "MatMulCommon", "[InferShapeRange] range[%ld, %ld] is incorrect.", range.at(i).first,
469	                range.at(i).second);
470	            return false;
471	        }
472	        if (range.at(i).second == INFINITE_RANGE) {
473	            // range {a, -1} -> new_range {a, MAX}
474	            new_range.emplace_back(std::make_pair(range.at(i).first, NORMALIZE_INFINITE_RANGE));
475	        } else {
476	            // range {a, b} -> new_range {a, b}
477	            new_range.emplace_back(range.at(i));
478	        }
479	    }
480	
481	    return true;
482	}
