484	static bool GetBatchIntersection(
485	    const char* op_name, std::pair<int64_t, int64_t>& a, std::pair<int64_t, int64_t>& b,
486	    std::pair<int64_t, int64_t>& out)
487	{
488	    // 存在1的情况，按范围比较大的情况broadcast
489	    if (a.first == 1 && b.first == 1) {
490	        out.first = 1;
491	        out.second = std::max(a.second, b.second);
492	        return true;
493	    }
494	    if (a.first == 1) {
495	        out.first = b.first;
496	        out.second = b.second;
497	        return true;
498	    }
499	    if (b.first == 1) {
500	        out.first = a.first;
501	        out.second = a.second;
502	        return true;
503	    }
504	    // 取交集
505	    out.first = std::max(a.first, b.first);
506	    out.second = std::min(a.second, b.second);
507	    // 交集不存在
508	    if (out.first > out.second || out.first == NORMALIZE_INFINITE_RANGE) {
509	        OP_LOGE(
510	            op_name, "[GetBatchIntersection] range[%ld, %ld] and range[%ld, %ld] don't have intersection.", a.first,
511	            a.second, b.first, b.second);
512	        return false;
513	    }
514	    return true;
515	}
