517	static bool GetKNIntersection(
518	    const char* op_name, const std::pair<int64_t, int64_t>& a, const std::pair<int64_t, int64_t>& b,
519	    std::pair<int64_t, int64_t>& out)
520	{
521	    // 取交集
522	    out.first = std::max(a.first, b.first);
523	    out.second = std::min(a.second, b.second);
524	    // 交集不存在
525	    if (out.first > out.second || out.first == NORMALIZE_INFINITE_RANGE) {
526	        OP_LOGE(
527	            op_name, "[GetKNIntersection] range[%ld, %ld] and range[%ld, %ld] don't have intersection.", a.first,
528	            a.second, b.first, b.second);
529	        return false;
530	    }
531	    return true;
532	}
