534	static void ExpendOneDimRange(
535	    size_t num_dim_x1, size_t num_dim_x2, std::vector<std::pair<int64_t, int64_t>>& shape_range_x1,
536	    std::vector<std::pair<int64_t, int64_t>>& shape_range_x2)
537	{
538	    // bmmv3支持x1为1维
539	    if (num_dim_x1 == 1) {
540	        std::pair<int64_t, int64_t> new_dim = {1, 1};
541	        shape_range_x1.insert(shape_range_x1.begin(), new_dim);
542	    }
543	    // bmmv3支持x2为1维
544	    if (num_dim_x2 == 1) {
545	        std::pair<int64_t, int64_t> new_dim = {1, 1};
546	        shape_range_x2.emplace_back(new_dim);
547	    }
548	}
