550	static void ReduceOneDimRange(
551	    size_t num_dim_x1, size_t num_dim_x2, size_t& num_dim_out,
552	    std::vector<std::pair<int64_t, int64_t>>& shape_range_out)
553	{
554	    // bmmv3支持x1为1维的还原
555	    if (num_dim_x1 == 1 && num_dim_x2 > 1) {
556	        num_dim_out -= 1;
557	        shape_range_out.erase(shape_range_out.end() - 2); // 去掉倒数第2维增加的m轴
558	    }
559	    // bmmv3支持x2为1维的还原
560	    if (num_dim_x2 == 1 && num_dim_x1 > 1) {
561	        num_dim_out -= 1;
562	        shape_range_out.pop_back(); // 去掉倒数第1维增加的n轴
563	    }
564	}
