566	static bool InferRangeBias(
567	    const char* op_name, std::vector<std::pair<int64_t, int64_t>>& new_shape_range_out, size_t idx_n,
568	    const gert::Range<gert::Shape>* bias_shape_range,
569	    const std::vector<std::pair<int64_t, int64_t>>& new_shape_range_x2)
570	{
571	    size_t num_dim_out = new_shape_range_out.size();
572	    if (bias_shape_range == nullptr) {
573	        new_shape_range_out[num_dim_out - 1] = new_shape_range_x2[idx_n];
574	    } else {
575	        auto bias_min_shape = bias_shape_range->GetMin();
576	        auto bias_max_shape = bias_shape_range->GetMax();
577	        OP_CHECK_IF(
578	            bias_min_shape == nullptr || bias_max_shape == nullptr,
579	            CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] bias min/max shape is null"), return false);
580	        size_t num_dim_bias = bias_min_shape->GetDimNum();
581	        // 数组长度为0，也是bias不存在，直接返回true不进行校验
582	        if (num_dim_bias == 0) {
583	            new_shape_range_out[num_dim_out - 1] = new_shape_range_x2[idx_n];
584	            return true;
585	        }
586	        // 初始化bias，转为vector形式
587	        std::vector<std::pair<int64_t, int64_t>> tmp_shape_range_bias;
588	        if (num_dim_out > num_dim_bias) {
589	            // 把前面差的轴补上
590	            for (size_t i = 0; i < num_dim_out - num_dim_bias; ++i) {
591	                tmp_shape_range_bias.emplace_back(std::make_pair(1, 1));
592	            }
593	        }
594	        for (size_t i = 0; i < num_dim_bias; ++i) {
595	            std::pair<int64_t, int64_t> new_dim = {bias_min_shape->GetDim(i), bias_max_shape->GetDim(i)};
596	            tmp_shape_range_bias.emplace_back(new_dim);
597	        }
598	        std::vector<std::pair<int64_t, int64_t>> new_shape_range_bias;
599	        OP_CHECK_IF(!InitializeRange(num_dim_out, tmp_shape_range_bias, new_shape_range_bias),
600	            CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] InitializeRange bias failed."),
601	            return false);
602	        // 按bias的batch轴校验并扩充，除去最后的2维，继承原有rt1.0逻辑
603	        for (size_t i = 0; i < num_dim_out - 2; ++i) {
604	            OP_CHECK_IF(
605	                !GetBatchIntersection(op_name, new_shape_range_out[i], new_shape_range_bias[i], new_shape_range_out[i]),
606	                CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] Infer bias batch range incorrect at dim[%zu].", i),
607	                return false);
608	        }
609	        if (!GetKNIntersection(op_name, new_shape_range_bias[num_dim_out - 1], new_shape_range_x2[idx_n],
610	                               new_shape_range_out[num_dim_out - 1])) {
611	            return false;
612	        }
613	    }
614	    return true;
615	}
616	
617	class InferShapeRangeBatchMatMul {
618	public:
619	    InferShapeRangeBatchMatMul(
620	        gert::InferShapeRangeContext* in_context, int32_t in_attr_adj_idx, size_t input_bias_index)
621	        : context(in_context),
622	          op_name(in_context->GetNodeName()),
623	          attr_adj_idx(in_attr_adj_idx),
624	          x1_shape_range(in_context->GetInputShapeRange(0)),
625	          x2_shape_range(in_context->GetInputShapeRange(1)),
626	          bias_shape_range(in_context->GetOptionalInputShapeRange(input_bias_index)),
627	          out_shape_range(in_context->GetOutputShapeRange(0)){};
628	    bool Init();
629	    bool InferShapeRange();
630	
631	protected:
632	    void SetOutput();
633	    gert::InferShapeRangeContext* context;
634	    const char* op_name;
635	    int32_t attr_adj_idx;
636	
637	    const gert::Range<gert::Shape>* x1_shape_range;
638	    const gert::Range<gert::Shape>* x2_shape_range;
639	    const gert::Range<gert::Shape>* bias_shape_range;
640	
641	    const bool* adj_x1;
642	    const bool* adj_x2;
643	    const gert::Shape* x1_min_shape;
644	    const gert::Shape* x1_max_shape;
645	    const gert::Shape* x2_min_shape;
646	    const gert::Shape* x2_max_shape;
647	    size_t num_dim_x1;
648	    size_t num_dim_x2;
649	    size_t num_dim_out;
650	    std::vector<std::pair<int64_t, int64_t>> src_shape_range_x1;
651	    std::vector<std::pair<int64_t, int64_t>> src_shape_range_x2;
652	
653	    gert::Range<gert::Shape>* out_shape_range;
654	    std::vector<std::pair<int64_t, int64_t>> new_shape_range_out;
655	};
656	bool InferShapeRangeBatchMatMul::Init()
657	{
658	    OP_CHECK_IF(
659	        x1_shape_range == nullptr || x2_shape_range == nullptr || out_shape_range == nullptr,
660	        CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] shape range is null"), return false);
661	
662	    const gert::RuntimeAttrs* attrs = context->GetAttrs();
663	    OP_CHECK_IF(attrs == nullptr, CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] attrs is null"), return false);
664	
665	    adj_x1 = attrs->GetAttrPointer<bool>(attr_adj_idx);
666	    adj_x2 = attrs->GetAttrPointer<bool>(attr_adj_idx + 1);
667	
668	    OP_CHECK_IF(
669	        adj_x1 == nullptr || adj_x2 == nullptr, CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] attribute is null"),
670	        return false);
671	
672	    x1_min_shape = x1_shape_range->GetMin();
673	    x1_max_shape = x1_shape_range->GetMax();
674	    x2_min_shape = x2_shape_range->GetMin();
675	    x2_max_shape = x2_shape_range->GetMax();
676	    OP_CHECK_IF(
677	        x1_min_shape == nullptr || x1_max_shape == nullptr || x2_min_shape == nullptr || x2_max_shape == nullptr,
678	        CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] min/max shape is null"), return false);
679	    num_dim_x1 = x1_min_shape->GetDimNum();
680	    num_dim_x2 = x2_min_shape->GetDimNum();
681	    // 初始化x1和x2，转为vector的形式
682	    for (size_t i = 0; i < num_dim_x1; ++i) {
683	        std::pair<int64_t, int64_t> new_dim = {x1_min_shape->GetDim(i), x1_max_shape->GetDim(i)};
684	        src_shape_range_x1.emplace_back(new_dim);
685	    }
686	    for (size_t i = 0; i < num_dim_x2; ++i) {
687	        std::pair<int64_t, int64_t> new_dim = {x2_min_shape->GetDim(i), x2_max_shape->GetDim(i)};
688	        src_shape_range_x2.emplace_back(new_dim);
689	    }
690	    return true;
691	}
692	
693	bool InferShapeRangeBatchMatMul::InferShapeRange()
694	{
695	    // bmmv3支持x1和x2为1维，输入的都为k轴
696	    ExpendOneDimRange(num_dim_x1, num_dim_x2, src_shape_range_x1, src_shape_range_x2);
697	    num_dim_out = std::max(src_shape_range_x1.size(), src_shape_range_x2.size());
698	    if (bias_shape_range != nullptr) {
699	        // bias也参与维度扩充
700	        size_t num_dim_bias = bias_shape_range->GetMin()->GetDimNum();
701	        num_dim_out = std::max(num_dim_out, num_dim_bias);
702	    }
703	    // 扩充x1和x2到一样的维度，用1在前面补充
704	    std::vector<std::pair<int64_t, int64_t>> new_shape_range_x1;
705	    OP_CHECK_IF(
706	        !InitializeRange(num_dim_out, src_shape_range_x1, new_shape_range_x1),
707	        CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] InitializeRange x1 failed."), return false);
708	    std::vector<std::pair<int64_t, int64_t>> new_shape_range_x2;
709	    OP_CHECK_IF(
710	        !InitializeRange(num_dim_out, src_shape_range_x2, new_shape_range_x2),
711	        CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] InitializeRange x2 failed."), return false);
712	    for (size_t i = 0; i < num_dim_out; ++i) {
713	        new_shape_range_out.emplace_back(NORMALIZE_FULL_RANGE);
714	    }
715	    // using index - 2 to get m_dim
716	    size_t idx_m = num_dim_out - 2;
717	    size_t idx_k_x1 = num_dim_out - 1;
718	    // using index - 2 to get k_dim
719	    size_t idx_k_x2 = num_dim_out - 2;
720	    size_t idx_n = num_dim_out - 1;
721	    // x1单轴时输入都为k轴，所以单轴时m和k的位置不因是否转置改变，x2同理
722	    if (*adj_x1 && num_dim_x1 != 1) {
723	        idx_m = num_dim_out - 1;
724	        // using index - 2 to get k_dim
725	        idx_k_x1 = num_dim_out - 2;
726	    }
727	    if (*adj_x2 && num_dim_x2 != 1) {
728	        idx_k_x2 = num_dim_out - 1;
729	        // using index - 2 to get n_dim
730	        idx_n = num_dim_out - 2;
731	    }
732	    // 推理所有维度的range，取交集
733	    // 推理batch（除去最后m、n这2维）
734	    for (size_t i = 0; i < num_dim_out - 2; ++i) {
735	        OP_CHECK_IF(
736	            !GetBatchIntersection(op_name, new_shape_range_x1[i], new_shape_range_x2[i], new_shape_range_out[i]),
737	            CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] Infer batch range incorrect at dim[%zu].", i),
738	            return false);
739	    }
740	    // 推理m，输出的倒数第2维度
741	    new_shape_range_out[num_dim_out - 2] = new_shape_range_x1[idx_m];
742	    // 推理k，不输出，只校验
743	    std::pair<int64_t, int64_t> k_range;
744	    OP_CHECK_IF(
745	        !GetKNIntersection(op_name, new_shape_range_x1[idx_k_x1], new_shape_range_x2[idx_k_x2], k_range),
746	        CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] Infer k range incorrect."), return false);
747	    // 从bias推理N和推理bias的batch
748	    OP_CHECK_IF(
749	        !InferRangeBias(op_name, new_shape_range_out, idx_n, bias_shape_range, new_shape_range_x2),
750	        CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] Infer n range incorrect."), return false);
751	
752	    // 设置输出range
753	    SetOutput();
754	    return true;
755	}
756	
757	void InferShapeRangeBatchMatMul::SetOutput()
758	{
759	    // bmmv3支持x1和x2为1维，返回前还原该维度
760	    ReduceOneDimRange(num_dim_x1, num_dim_x2, num_dim_out, new_shape_range_out);
761	    out_shape_range->GetMin()->SetDimNum(num_dim_out);
762	    out_shape_range->GetMax()->SetDimNum(num_dim_out);
763	    for (size_t i = 0; i < num_dim_out; ++i) {
764	        out_shape_range->GetMin()->SetDim(i, new_shape_range_out[i].first);
765	        // 无穷大还原回-1
766	        if (new_shape_range_out[i].second == NORMALIZE_INFINITE_RANGE) {
767	            new_shape_range_out[i].second = INFINITE_RANGE;
768	        }
769	        out_shape_range->GetMax()->SetDim(i, new_shape_range_out[i].second);
770	    }
771	}
772	
773	ge::graphStatus InferShapeRangeForBatchMatMul(
774	    gert::InferShapeRangeContext* context, const int32_t attr_adj_idx, const size_t input_bias_index)
775	{
776	    InferShapeRangeBatchMatMul batchMatMulInferRange(context, attr_adj_idx, input_bias_index);
777	    auto op_name = context->GetNodeName();
778	    OP_CHECK_IF(
779	        !batchMatMulInferRange.Init(), CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] Failed to init shape range"),
780	        return ge::GRAPH_FAILED);
781	    OP_CHECK_IF(
782	        !batchMatMulInferRange.InferShapeRange(),
783	        CUBE_INNER_ERR_REPORT(op_name, "[InferShapeRange] Failed to infer output shape range"),
784	        return ge::GRAPH_FAILED);
785	    return ge::GRAPH_SUCCESS;
786	}
787	} // namespace NN
788	} // namespace Ops
