20	using namespace gert;
21	namespace {
22	constexpr size_t MATMUL_MIN_SHAPE_SIZE = 2;
23	constexpr size_t MATMUL_MAX_SHAPE_SIZE = 4;
24	constexpr size_t MATMUL_SLICE_SHAPE_SIZE = 3;
25	constexpr size_t MATMUL_BIAS_IDX = 2; // input_bias index is different with op_type
26	constexpr int64_t BLOCK_SIZE = 16;
27	constexpr int64_t UNKNOWN_DIM = -1;
28	constexpr int64_t UNKNOWN_DIM_NUM = -2;
29	
30	void InferComplementedInput(
31	    Shape& shape_x1_new, Shape& shape_x2_new, bool& shapeX1ReshapeFlag, bool& shapeX2ReshapeFlag)
32	{
33	    if (shape_x1_new.GetDimNum() == 1 && shape_x1_new.GetDim(0) > 0) {
34	        shapeX1ReshapeFlag = true;
35	        int64_t ori_dim = shape_x1_new.GetDim(0);
36	        shape_x1_new.SetDimNum(MATMUL_MIN_SHAPE_SIZE);
37	        shape_x1_new.SetDim(0, 1);
38	        shape_x1_new.SetDim(1, ori_dim);
39	    }
40	
41	    if (shape_x2_new.GetDimNum() == 1 && shape_x2_new.GetDim(0) > 0) {
42	        shapeX2ReshapeFlag = true;
43	        int64_t ori_dim = shape_x2_new.GetDim(0);
44	        shape_x2_new.SetDimNum(MATMUL_MIN_SHAPE_SIZE);
45	        shape_x2_new.SetDim(0, ori_dim);
46	        shape_x2_new.SetDim(1, 1);
47	    }
48	}
49	
50	static void InferComplementedOutput(bool shapeX1ReshapeFlag, bool shapeX2ReshapeFlag, Shape& shape_out)
51	{
52	    size_t dimNum = shape_out.GetDimNum();
53	    if (dimNum >= MATMUL_MIN_SHAPE_SIZE) {
54	        if (shapeX1ReshapeFlag && !shapeX2ReshapeFlag) {
55	            shape_out.SetDim(dimNum - MATMUL_MIN_SHAPE_SIZE, shape_out.GetDim(dimNum - 1));
56	            shape_out.SetDimNum(dimNum - 1);
57	        }
58	        if (!shapeX1ReshapeFlag && shapeX2ReshapeFlag) {
59	            shape_out.SetDimNum(dimNum - 1);
60	        }
61	    }
62	}
63	
64	bool CheckIsUnknownDimNum(const gert::Shape& shape)
65	{
66	    return shape.GetDimNum() == 1 && shape.GetDim(0) == UNKNOWN_DIM_NUM;
67	}
68	
69	void UpdateUnknowDimNumToUnkownRank(gert::Shape& shape)
70	{
71	    if (CheckIsUnknownDimNum(shape)) {
72	        shape.SetDimNum(MATMUL_MIN_SHAPE_SIZE);
73	        shape.SetDim(0, UNKNOWN_DIM);
74	        shape.SetDim(1, UNKNOWN_DIM);
75	    }
76	}
77	
78	bool UpdateOutputShapeByBias(const std::string& op_name, gert::Shape* shape_out, const gert::Shape* shape_bias)
79	{
80	    if (shape_bias != nullptr && shape_bias->GetDimNum() > 0) {
81	        Shape shape_bias_new(*shape_bias);
82	        UpdateUnknowDimNumToUnkownRank(shape_bias_new);
83	        int64_t bias_dim = shape_bias_new.GetDimNum();
84	        if (shape_bias_new.GetDim(bias_dim - 1) != UNKNOWN_DIM && shape_out->GetDim(1) != UNKNOWN_DIM) {
85	            OP_CHECK_IF(
86	                shape_bias_new.GetDim(bias_dim - 1) != shape_out->GetDim(1),
87	                OP_LOGE(
88	                    op_name, "The dimension of n [%ld] and bias [%ld] tensors must be the same", shape_out->GetDim(1),
89	                    shape_bias_new.GetDim(bias_dim - 1)),
90	                return false);
91	        }
92	        if (shape_bias_new.GetDim(bias_dim - 1) != UNKNOWN_DIM && shape_out->GetDim(1) == UNKNOWN_DIM) {
93	            shape_out->SetDim(1, shape_bias_new.GetDim(bias_dim - 1));
94	        }
95	    }
96	    return true;
97	}
98	
99	static ge::graphStatus InferShapeForAiInfraMatmul(InferShapeContext* context)
100	{
101	    auto op_name = context->GetNodeName();
102	    auto shape_x1 = context->GetInputShape(0);
103	    auto shape_x2 = context->GetInputShape(1);
104	    auto shape_out = context->GetOutputShape(0);
105	    auto tensor_x1 = context->GetInputDesc(0);
106	    auto attrs = context->GetAttrs();
107	    OP_CHECK_IF(
108	        shape_x1 == nullptr || shape_x2 == nullptr || shape_out == nullptr || tensor_x1 == nullptr || attrs == nullptr,
109	        CUBE_INNER_ERR_REPORT(op_name, "shape or attrs is null"), return ge::GRAPH_FAILED);
110	    auto shape_bias = context->GetOptionalInputShape(MATMUL_BIAS_IDX);
111	    if (CheckIsUnknownDimNum(*shape_x1) && CheckIsUnknownDimNum(*shape_x2) &&
112	        (shape_bias == nullptr || CheckIsUnknownDimNum(*shape_bias))) {
113	        shape_out->SetDimNum(1);
114	        shape_out->SetDim(0, UNKNOWN_DIM_NUM);
115	        return ge::GRAPH_SUCCESS;
116	    }
117	
118	    const bool* transA = attrs->GetAttrPointer<bool>(0);
119	    const bool* transB = attrs->GetAttrPointer<bool>(1);
120	    OP_CHECK_IF(
121	        transA == nullptr || transB == nullptr, CUBE_INNER_ERR_REPORT(op_name, "attribute is null"),
122	        return ge::GRAPH_FAILED);
123	
124	    OP_LOGD(
125	        context->GetNodeName(), "x1_shape: %s, x2_shape: %s, transpose_x1: %d, transpose_x2: %d",
126	        Ops::Base::ToString(*shape_x1).c_str(), Ops::Base::ToString(*shape_x2).c_str(), *transA, *transB);
127	
128	    ge::DataType dtype = tensor_x1->GetDataType();
129	    if (dtype == ge::DT_FLOAT) {
130	        OP_LOGW(op_name, "%s fp32 op has poor performance!", context->GetNodeName());
131	    }
132	
133	    Shape shape_x1_new(*shape_x1);
134	    Shape shape_x2_new(*shape_x2);
135	    UpdateUnknowDimNumToUnkownRank(shape_x1_new);
136	    UpdateUnknowDimNumToUnkownRank(shape_x2_new);
137	    bool shapeX1ReshapeFlag = false;
138	    bool shapeX2ReshapeFlag = false;
139	
140	    InferComplementedInput(shape_x1_new, shape_x2_new, shapeX1ReshapeFlag, shapeX2ReshapeFlag);
141	    if (attrs->GetAttrNum() >= 5) { // 5 attrs: transpose_x1, transpose_x2, offset_x, input_size, hidden_size
142	        auto input_size = attrs->GetAttrPointer<int64_t>(3);  // 3: input_size
143	        auto hidden_size = attrs->GetAttrPointer<int64_t>(4); // 4: hidden_size
144	        if (input_size != nullptr && hidden_size != nullptr && *input_size > 0 && *hidden_size > 0) {
145	            OP_LOGD(op_name, "get private attr, input_size: %ld, hidden_size: %ld", *input_size, *hidden_size);
146	            shape_x2_new.SetDim(1, shape_x1_new.GetDim(1));
147	            OP_CHECK_IF(
148	                *input_size > std::numeric_limits<int64_t>::max() - BLOCK_SIZE + 1,
149	                OP_LOGE(op_name, "input_size %ld is too large and will cause overflow of int64.", *input_size),
150	                return ge::GRAPH_FAILED);
151	            int64_t align_dim = (*input_size + BLOCK_SIZE - 1) / BLOCK_SIZE * BLOCK_SIZE +
152	                                (*hidden_size + BLOCK_SIZE - 1) / BLOCK_SIZE * BLOCK_SIZE;
153	            shape_x2_new.SetDim(0, align_dim);
154	        }
155	    }
156	
157	    OP_LOGD(op_name, "check the input shape length.");
158	    size_t dimNumX1 = shape_x1_new.GetDimNum();
159	    // dimX1= 2, 3(slice), 4(NZ)
160	    if (dimNumX1 < MATMUL_MIN_SHAPE_SIZE ||  dimNumX1 > MATMUL_MAX_SHAPE_SIZE) {
161	        CUBE_INNER_ERR_REPORT(op_name, "first input dim num[%zu] is not between [2, 4]!", shape_x1_new.GetDimNum());
162	        return ge::GRAPH_FAILED;
163	    }
164	
165	    size_t idxM = 0UL;
166	    size_t idxKA = 1UL;
167	    size_t idxKB = 0UL;
168	    size_t idxN = 1UL;
169	
170	    if (*transA) {
171	        idxM = 1UL;
172	        idxKA = 0UL;
173	    } else if (dimNumX1 == MATMUL_SLICE_SHAPE_SIZE) {
174	        idxKA = 2UL;  // k in dim 2
175	        idxM = 1UL;
176	    } else {
177	        ; // 无效dimNumX1
178	    }
179	
180	    if (*transB) {
181	        idxKB = 1UL;
182	        idxN = 0UL;
183	    }
184	    // 3d slice: m = batch * sliceM
185	    auto m = dimNumX1 == MATMUL_SLICE_SHAPE_SIZE ? shape_x1_new.GetDim(idxM) * shape_x1_new.GetDim(0) :
186	                                                   shape_x1_new.GetDim(idxM);
187	    auto n = shape_x2_new.GetDim(idxN);
188	    if (shape_x1_new.GetDim(idxKA) != UNKNOWN_DIM && shape_x2_new.GetDim(idxKB) != UNKNOWN_DIM) {
189	        OP_CHECK_IF(
190	            shape_x1_new.GetDim(idxKA) != shape_x2_new.GetDim(idxKB),
191	            CUBE_INNER_ERR_REPORT(
192	                op_name, "The k-axis of a(%ld) and b(%ld) tensors must be the same", shape_x1_new.GetDim(idxKA),
193	                shape_x2_new.GetDim(idxKB)),
194	            return ge::GRAPH_FAILED);
195	    }
196	
197	    shape_out->SetDimNum(MATMUL_MIN_SHAPE_SIZE);
198	    shape_out->SetDim(0, m);
199	    shape_out->SetDim(1, n);
200	    if (!UpdateOutputShapeByBias(op_name, shape_out, shape_bias)) {
201	        return ge::GRAPH_FAILED;
202	    }
203	    InferComplementedOutput(shapeX1ReshapeFlag, shapeX2ReshapeFlag, *shape_out);
204	    OP_LOGD(op_name, "end infershape.");
205	    return ge::GRAPH_SUCCESS;
206	}
207	
208	} // namespace
209	namespace ops {
210	    IMPL_OP_INFERSHAPE(AiInfraMatmul).InferShape(InferShapeForAiInfraMatmul);
211	}
