#include <gtest/gtest.h>
#include <iostream>
#include "infer_shape_context_faker.h"
#include "infer_shape_case_executor.h"
#include "base/registry/op_impl_space_registry_v2.h"

class ChunkGatedDeltaRuleRecurrenceProto : public testing::Test
{
protected:
    static void SetUpTestCase()
    {
        std::cout << "ChunkGatedDeltaRuleRecurrenceInferShape SetUp" << std::endl;
    }

    static void TearDownTestCase()
    {
        std::cout << "ChunkGatedDeltaRuleRecurrenceInferShape TearDown" << std::endl;
    }
};

/*
* 测试用例描述：ChunkGatedDeltaRuleRecurrence算子proto功能验证
* 输入：入参value的shape：{headNum, chunkNum, chunkSize, vDim}
* 预期结果：推断出attn_inter_out以及v_new_out的shape：{headNum, chunkNum, chunkSize, vDim}
*/

TEST_F(ChunkGatedDeltaRuleRecurrenceProto, Ut_ChunkGatedDeltaRuleRecurrenceProto_Check_InferShape)
{
    uint32_t batchNum = 1024;
    uint32_t headNum = 48;
    uint32_t kDim = 128;
    uint32_t vDim = 128;
    uint32_t chunkNum = 256;
    uint32_t chunkSize = 64;
    gert::InfershapeContextPara infershapeContextPara(
        "AiInfraChunkGatedDeltaRuleRecurrence",
        {
            {{{batchNum, headNum, vDim, kDim}, {batchNum, headNum, vDim, kDim}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{headNum, chunkNum, chunkSize, kDim}, {headNum, chunkNum, chunkSize, kDim}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{headNum, chunkNum, chunkSize, vDim}, {headNum, chunkNum, chunkSize, vDim}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{headNum, chunkNum, chunkSize, kDim}, {headNum, chunkNum, chunkSize, kDim}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{headNum, chunkNum, chunkSize, kDim}, {headNum, chunkNum, chunkSize, kDim}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{headNum, chunkNum, chunkSize, 1}, {headNum, chunkNum, chunkSize, 1}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{batchNum + 1}, {batchNum + 1}}, ge::DT_INT32, ge::FORMAT_ND}
        },
        {
            {{{}, {}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{}, {}}, ge::DT_FLOAT, ge::FORMAT_ND},
            {{{}, {}}, ge::DT_FLOAT, ge::FORMAT_ND}
        });
    std::vector<std::vector<int64_t>> expectOutputShape = {
        {batchNum, headNum, vDim, kDim},
        {headNum, chunkNum, chunkSize, vDim},
        {headNum, chunkNum, chunkSize, vDim}
    };
    ExecuteTestCase(infershapeContextPara, ge::GRAPH_SUCCESS, expectOutputShape);
}
